-- TEST RUN exams: one short 5-question practice exam for EACH specialty (Critical Care, Perioperative,
-- Anaesthesia, Nephrology). New private-class students use it to try the Exam Room before the real mocks.
-- Open from now until 31 Dec 2026, 10 minutes, up to 3 attempts, answers shown after each question.
-- Questions are hidden exam-only copies that are NOT in any of the mock exams. Safe to run more than once.
set lock_timeout = '5s';
begin;
alter table public.exam_exams add column if not exists is_test boolean not null default false;
create temporary table tnew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
insert into tnew values
(1, 1, 'Test Run 5Q — Critical Care Nursing (Nov 2026)', 'Test Run · Critical Care Nursing', 'Most of the oxygen carried in arterial blood is:', '["Dissolved in plasma", "Bound to albumin", "Carried as bicarbonate", "Bound to haemoglobin"]'::jsonb, 3, 'CaO2 = (Hb × SaO2 × 1.34) + (PaO2 × 0.003 per mmHg). Almost all of it is the haemoglobin-bound part.', 'Test Run'),
(1, 2, 'Test Run 5Q — Critical Care Nursing (Nov 2026)', 'Test Run · Critical Care Nursing', 'Professional nurses are responsible for making clinical decisions to', '["Take immediate action when a patient''s condition worsens.", "Apply clear textbook solutions to patients'' problems.", "Prove traditional methods of providing nursing care to patients.", "Formulate standardized care plans for groups of patients"]'::jsonb, 0, 'Taking prompt clinical action as a patient''s condition changes reflects professional clinical decision-making.', 'Test Run'),
(1, 3, 'Test Run 5Q — Critical Care Nursing (Nov 2026)', 'Test Run · Critical Care Nursing', 'In the treatment of alcohol withdrawal there are three line management', '["Medication, Special therapy and Group therapy", "Supportive, Medication and Special procedure", "Supportive, Medical procedure and Medication", "Supportive group, medical management"]'::jsonb, 2, 'Alcohol withdrawal management follows supportive care, medical procedures, and medication together.', 'Test Run'),
(1, 4, 'Test Run 5Q — Critical Care Nursing (Nov 2026)', 'Test Run · Critical Care Nursing', 'Preload is best defined as:', '["The aortic diastolic pressure", "The end-diastolic volume of the ventricle", "The intrinsic contractility of heart muscle", "The wall tension the ventricle develops during ejection"]'::jsonb, 1, 'Preload is the ventricular end-diastolic volume (fibre stretch) before contraction.', 'Test Run'),
(1, 5, 'Test Run 5Q — Critical Care Nursing (Nov 2026)', 'Test Run · Critical Care Nursing', 'The patient has vomiting that is very similar to coffee grounds. Where can the location of the bleeding be?', '["Large Intestine (colon)", "Upper GI Tract", "Small Intestine", "Rectum"]'::jsonb, 1, 'Coffee-ground emesis reflects digested blood from an upper GI source.', 'Test Run'),
(2, 1, 'Test Run 5Q — Perioperative Nursing (Nov 2026)', 'Test Run · Perioperative Nursing', 'A postoperative patient is found to have signs of infection at the surgical site. What is the most appropriate action by the nurse?', '["Keep the wound dry and uncovered", "Perform frequent dressing changes", "Administer prescribed antibiotics", "Apply ice to reduce swelling"]'::jsonb, 2, 'Prescribed antibiotics treat the underlying infection at the surgical site.', 'Test Run'),
(2, 2, 'Test Run 5Q — Perioperative Nursing (Nov 2026)', 'Test Run · Perioperative Nursing', 'A patient is at risk for developing post-operative deep vein thrombosis (DVT). What nursing interventions can help prevent DVT in the post-operative period?', '["Monitor for signs and symptoms of DVT, such as swelling or pain in one leg", "Apply pneumatic compression devices to promote circulation", "Encourage early mobilization and activity", "Administer anticoagulant medications as prescribed"]'::jsonb, 3, 'Prescribed anticoagulant medication reduces clot formation risk in patients at risk for postoperative DVT.', 'Test Run'),
(2, 3, 'Test Run 5Q — Perioperative Nursing (Nov 2026)', 'Test Run · Perioperative Nursing', 'A patient in the ICU is at risk for developing delirium. What nursing interventions can help prevent delirium?', '["Limiting visitation from family members", "Keeping the environment quiet and calm", "Restraining the patient to prevent wandering", "Administering sedatives regularly"]'::jsonb, 1, 'A calm, quiet environment with orientation cues helps prevent and manage ICU delirium.', 'Test Run'),
(2, 4, 'Test Run 5Q — Perioperative Nursing (Nov 2026)', 'Test Run · Perioperative Nursing', 'A patient is at risk for developing a pressure ulcer following surgery. What nursing interventions can help prevent pressure ulcers in the post-operative period?', '["Turn and reposition the patient regularly", "Use tight dressings to prevent skin breakdown", "Apply direct pressure to bony prominences", "Encourage the patient to lie on the affected side"]'::jsonb, 0, 'Regular turning and repositioning relieves pressure over bony prominences, reducing pressure ulcer risk.', 'Test Run'),
(2, 5, 'Test Run 5Q — Perioperative Nursing (Nov 2026)', 'Test Run · Perioperative Nursing', 'A patient in the ICU develops signs of hypovolemic shock postoperatively. What interventions should the nurse prioritize?', '["Elevating the legs", "Increasing IV fluid rate", "Monitoring vital signs closely", "Administering vasopressors"]'::jsonb, 1, 'Increasing IV fluid administration restores circulating volume in hypovolaemic shock.', 'Test Run'),
(3, 1, 'Test Run 5Q — Anaesthesia Nursing (Nov 2026)', 'Test Run · Anaesthesia Nursing', 'Under anaesthesia, the anaesthetist controls the head during transfer mainly to:', '["Protect the airway and cervical spine", "Check the patient''s identity band against the list again", "Count the transfer staff aloud", "Keep the patient''s eyes closed"]'::jsonb, 0, 'The team moves on the anaesthetist''s command.', 'Test Run'),
(3, 2, 'Test Run 5Q — Anaesthesia Nursing (Nov 2026)', 'Test Run · Anaesthesia Nursing', 'Theatre traffic is best controlled by:', '["Encouraging staff to change rooms frequently", "Keeping the theatre doors propped wide open", "Allowing students to walk freely in and out so they can see each step", "Limiting the number of people and movement during surgery"]'::jsonb, 3, 'Fewer people means fewer airborne bacteria.', 'Test Run'),
(3, 3, 'Test Run 5Q — Anaesthesia Nursing (Nov 2026)', 'Test Run · Anaesthesia Nursing', 'Hand hygiene before putting on sterile gloves for minor procedures can be done with:', '["Nothing at all, as the gloves themselves are sterile", "A dry paper towel only, wiping each finger and the palm in turn for a minute", "An alcohol-based surgical hand rub, if the hands are visibly clean", "Plain tap water only, as gloves will cover the hands"]'::jsonb, 2, 'Wash with soap and water first if the hands are soiled.', 'Test Run'),
(3, 4, 'Test Run 5Q — Anaesthesia Nursing (Nov 2026)', 'Test Run · Anaesthesia Nursing', 'According to the Spaulding classification, a flexible gastroscope (which contacts mucous membranes) requires, at minimum:', '["Sterilisation", "High-level disinfection", "Low-level disinfection", "Cleaning with detergent only"]'::jsonb, 1, 'Critical items (enter sterile tissue or blood) must be sterile; semi-critical items (contact mucous membranes or non-intact skin) need at least high-level disinfection; non-critical items (intact skin) need low-level disinfection.', 'Test Run'),
(3, 5, 'Test Run 5Q — Anaesthesia Nursing (Nov 2026)', 'Test Run · Anaesthesia Nursing', 'A ''neutral zone'' for sharps in theatre means:', '["The surgeon keeps all the needles in one hand so they are never dropped", "Needles are recapped before being passed back", "Sharps are left anywhere on the drapes to save time", "Sharps are placed in a set area, not passed hand to hand"]'::jsonb, 3, 'This hands-free technique reduces needlestick injuries.', 'Test Run'),
(4, 1, 'Test Run 5Q — Nephrology Nursing (Nov 2026)', 'Test Run · Nephrology Nursing', 'A nurse is interpreting ABG results for a patient and notes a normal PaO₂ and a high PaCO₂. This is an example of:', '["Uncompensated metabolic acidosis", "Uncompensated respiratory alkalosis", "Normal findings", "Uncompensated respiratory acidosis"]'::jsonb, 3, 'A normal PaO₂ and a high PaCO₂ indicate that the patient is able to oxygenate but is not able to ventilate effectively. The high PaCO₂ causes respiratory acidosis. If the pH is low and the HCO₃⁻ is normal, it is uncompensated.', 'Test Run'),
(4, 2, 'Test Run 5Q — Nephrology Nursing (Nov 2026)', 'Test Run · Nephrology Nursing', 'Which vascular access is generally preferred for long-term hemodialysis due to lower infection and thrombosis rates compared with other options?', '["Temporary femoral catheter", "Peripheral IV line", "Arteriovenous fistula", "Tunneled central venous catheter"]'::jsonb, 2, 'An arteriovenous fistula, created by surgically connecting an artery and vein, has the lowest rates of infection and thrombosis and the best long-term patency of all access types.', 'Test Run'),
(4, 3, 'Test Run 5Q — Nephrology Nursing (Nov 2026)', 'Test Run · Nephrology Nursing', 'A patient with hypernatremia (Na⁺ 160 mEq/L) is lethargic. Which fluid should the nurse administer?', '["0.9% saline", "D5W", "3% saline", "Lactated Ringer’s"]'::jsonb, 1, 'Hypernatremia requires free water (e.g., D5W) to correct hypertonicity. Saline solutions worsen hypernatremia.', 'Test Run'),
(4, 4, 'Test Run 5Q — Nephrology Nursing (Nov 2026)', 'Test Run · Nephrology Nursing', 'A passive leg raise predicts fluid responsiveness when it raises stroke volume or cardiac output by more than:', '["50%", "1%", "100%", "10%"]'::jsonb, 3, 'Passive leg raising returns about 300 mL of blood from the legs, and the effect is reversible.', 'Test Run'),
(4, 5, 'Test Run 5Q — Nephrology Nursing (Nov 2026)', 'Test Run · Nephrology Nursing', 'The target urine output in an adult burns patient during fluid resuscitation is:', '["0.5–1.0ml/kg/hr", "5ml/kg/hr", "2–3ml/kg/hr", "0.1–0.2ml/kg/hr"]'::jsonb, 0, 'Urine output is the most practical bedside marker of adequate fluid resuscitation, and 0.5–1.0ml/kg/hr is the target range in adults.', 'Test Run');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '🧪', false
from tnew d where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set title = 'Test Run — Critical Care Nursing (5 Questions)' where title = 'Test Run — Critical Care Nursing (20 Questions)' and not exists (select 1 from public.exam_exams where title = 'Test Run — Critical Care Nursing (5 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'TEST RUN for Critical Care Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', specialty = 'ccn', attempts_allowed = 3, is_test = true,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 10 where title = 'Test Run — Critical Care Nursing (5 Questions)';
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids, show_answers, show_score,
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty, is_test)
select 'Test Run — Critical Care Nursing (5 Questions)', 'TEST RUN for Critical Care Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 10, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 3, 'relaxed', 'ccn', true
where not exists (select 1 from public.exam_exams where title = 'Test Run — Critical Care Nursing (5 Questions)');
update public.exam_exams set title = 'Test Run — Perioperative Nursing (5 Questions)' where title = 'Test Run — Perioperative Nursing (20 Questions)' and not exists (select 1 from public.exam_exams where title = 'Test Run — Perioperative Nursing (5 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'TEST RUN for Perioperative Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', specialty = 'periop', attempts_allowed = 3, is_test = true,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 10 where title = 'Test Run — Perioperative Nursing (5 Questions)';
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids, show_answers, show_score,
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty, is_test)
select 'Test Run — Perioperative Nursing (5 Questions)', 'TEST RUN for Perioperative Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 10, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 3, 'relaxed', 'periop', true
where not exists (select 1 from public.exam_exams where title = 'Test Run — Perioperative Nursing (5 Questions)');
update public.exam_exams set title = 'Test Run — Anaesthesia Nursing (5 Questions)' where title = 'Test Run — Anaesthesia Nursing (20 Questions)' and not exists (select 1 from public.exam_exams where title = 'Test Run — Anaesthesia Nursing (5 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'TEST RUN for Anaesthesia Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', specialty = 'anaes', attempts_allowed = 3, is_test = true,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 10 where title = 'Test Run — Anaesthesia Nursing (5 Questions)';
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids, show_answers, show_score,
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty, is_test)
select 'Test Run — Anaesthesia Nursing (5 Questions)', 'TEST RUN for Anaesthesia Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 10, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 3, 'relaxed', 'anaes', true
where not exists (select 1 from public.exam_exams where title = 'Test Run — Anaesthesia Nursing (5 Questions)');
update public.exam_exams set title = 'Test Run — Nephrology Nursing (5 Questions)' where title = 'Test Run — Nephrology Nursing (20 Questions)' and not exists (select 1 from public.exam_exams where title = 'Test Run — Nephrology Nursing (5 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4), instructions = 'TEST RUN for Nephrology Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', specialty = 'neph', attempts_allowed = 3, is_test = true,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 10 where title = 'Test Run — Nephrology Nursing (5 Questions)';
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids, show_answers, show_score,
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty, is_test)
select 'Test Run — Nephrology Nursing (5 Questions)', 'TEST RUN for Nephrology Nursing. 5 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 10 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 10, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4),
       true, true, 100, true, true, 3, 'relaxed', 'neph', true
where not exists (select 1 from public.exam_exams where title = 'Test Run — Nephrology Nursing (5 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at, attempts_allowed from public.exam_exams where title like 'Test Run — %' order by specialty;
commit;
